def two_sum_optimized(nums, target):
    seen = set()
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [nums.index(complement), i]
        seen.add(num)
    return []

print(two_sum_optimized([1, 2, 3, 4, 5], 9))

