def contains_substring(text, pat):
    n = len(text)
    m = len(pat)
    if m == 0:
        return True
    if m > n:
        return False
    for i in range(n - m + 1):
        match = True
        for j in range(m):
            if text[i + j] != pat[j]:
                match = False
                break
        if match:
            return True
    return False

# Example usage
print(contains_substring('abracadabra', 'cad'))
print(contains_substring('abracadabra', 'xyz'))

def find_first_duplicate(filename):
    with open(filename, 'r') as f:
        ids = [line.strip() for line in f if line.strip()]
    n = len(ids)
    for i in range(n):
        for j in range(i + 1, n):
            if ids[i] == ids[j]:
                print('Duplicate found:', ids[i])
                return
    print('No duplicates')

# Example usage
