def max_product_brute(nums):
    if len(nums) < 2:
        return None
    max_prod = None
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            prod = nums[i] * nums[j]
            if max_prod is None or prod > max_prod:
                max_prod = prod
    return max_prod

# Example usage
print(max_product_brute([3, 6, -2, -5, 7]))
print(max_product_brute([1]))
